# RANK CONSTANTS
# =============================================================================

RANKS = "AKQJT98765432"
SUITS = "shdc"

# Rank value mapping: A=14, K=13, Q=12, ..., 2=2
RANK_VALUES = {r: 14 - i for i, r in enumerate(RANKS)}

# Reverse mapping: 14='A', 13='K', etc.
RANK_CHARS = {v: k for k, v in RANK_VALUES.items()}
RANK_CHARS[1] = 'A'  # Low ace for wheel straights


