# =============================================================================
# CATEGORY CLASSIFICATION HELPERS
# =============================================================================

def is_monster(category: str) -> bool:
    """Check if category is a monster hand (trips or better)."""
    return CATEGORY_BASE.get(category, 0) >= CATEGORY_BASE['trips']


def is_strong_made(category: str) -> bool:
    """Check if category is a strong made hand (two pair or better)."""
    return CATEGORY_BASE.get(category, 0) >= CATEGORY_BASE['two_pair']


def is_made_hand(category: str) -> bool:
    """Check if category is a made hand (any pair or better)."""
    return CATEGORY_BASE.get(category, 0) >= CATEGORY_BASE['low_pair']


def is_draw(category: str) -> bool:
    """Check if category is a draw."""
    base = CATEGORY_BASE.get(category, 0)
    return CATEGORY_BASE['straight_draw'] <= base < CATEGORY_BASE['low_pair']


# =============================================================================
# CORE DETECTION FUNCTIONS
# =============================================================================

def check_straight(ranks: List[int]) -> Optional[int]:
    """
    Check for a straight in the given ranks.
    
    Args:
        ranks: List of rank values (2-14, where 14=Ace)
    
    Returns:
        High card of the straight (5-14), or None if no straight
        
    Note:
        Handles wheel (A-2-3-4-5) by adding low ace (1) to unique ranks.
    """
    unique = set(ranks)
    
    # Add low ace for wheel check
    if 14 in unique:
        unique.add(1)
    
    # Check from highest possible straight down
    for high in range(14, 4, -1):
        needed = set(range(high - 4, high + 1))
        if needed <= unique:
            return high
    
    return None


def has_straight_draw(ranks: List[int]) -> bool:
    """
    Check for open-ended straight draw or gutshot.
    
    Args:
        ranks: List of rank values
    
    Returns:
        True if there's a straight draw possibility
        
    Note:
        Detects OESD (4 cards within 5 ranks) and gutshots.
    """
    unique = sorted(set(ranks), reverse=True)
    
    # Add low ace for wheel potential
    if 14 in unique:
        unique.append(1)
    
    # Check for 4 cards within 5 ranks (OESD or gutshot)
    for i in range(len(unique) - 3):
        window = unique[i:i+4]
        if max(window) - min(window) <= 4:
            return True
    
    return False


def count_straight_outs(ranks: List[int]) -> int:
    """
    Count outs to complete a straight.
    
    Args:
        ranks: List of rank values
    
    Returns:
        Number of outs (0, 4 for gutshot, 8 for OESD)
    """
    unique = sorted(set(ranks))
    
    # Add low ace
    if 14 in unique:
        unique = [1] + unique
    
    # Check for OESD (8 outs) or gutshot (4 outs)
    best_outs = 0
    
    for i in range(len(unique)):
        for j in range(i + 1, min(i + 5, len(unique))):
            window = unique[i:j+1]
            if len(window) >= 4:
                span = window[-1] - window[0]
                if span == 3 and len(window) == 4:
                    # Open-ended: e.g., 5-6-7-8 needs 4 or 9
                    best_outs = max(best_outs, 8)
                elif span == 4 and len(window) == 4:
                    # Gutshot: e.g., 5-6-8-9 needs 7
                    best_outs = max(best_outs, 4)
    
    return best_outs


