def normalize_hand(hand: str) -> str:
    """
    Normalize hand notation to canonical form.
    
    Rules:
    - High card first
    - Lowercase suffix (s/o)
    
    Args:
        hand: Hand notation like "KAs" or "ak" or "AKs"
    
    Returns:
        Canonical form like "AKs"
    """
    hand = hand.strip()
    if len(hand) < 2:
        return hand.upper()
    
    r1, r2 = hand[0].upper(), hand[1].upper()
    suffix = hand[2:].lower() if len(hand) > 2 else ""
    
    # Ensure high card first
    if RANK_VALUES.get(r2, 0) > RANK_VALUES.get(r1, 0):
        r1, r2 = r2, r1
    
    return f"{r1}{r2}{suffix}"


